    rdn RSEGS M (Z_to_bv 64 (bv_unsigned pp + Z.of_nat (length a0s))) 8 = Some t8 ->
    srealizes RSEGS scfg (mkCfg (mkst R (Z_to_bv 64 0xa17d8) M (seg_rom RSEGS)) model)
